using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Text;
using System.Text.Json;

namespace BlockLogger.AntiCheat;

internal static class AntiCheatDefaultBlacklistProfileData
{
	private sealed class Payload
	{
		public List<string> ModIds { get; set; } = new List<string>();

		public List<AntiCheatForbiddenFingerprint> Fingerprints { get; set; } = new List<AntiCheatForbiddenFingerprint>();
	}

	public const string ProfileId = "newfies-default-unfair-mods";

	public const string ProfileName = "Newfie's Unfair Mods";

	public const string SourceConfigSha256 = "da06fee1516e0ebdcfdfdf6c1d332a1e2084e2165a7a05f2cd9f520fbf752931";

	private static readonly string CompressedPayloadBase64 = "";

	public static AntiCheatBlacklistProfile CreateProfile()
	{
		Payload payload = ReadPayload();
		long num = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
		return new AntiCheatBlacklistProfile
		{
			Id = "newfies-default-unfair-mods",
			Name = "Newfie's Unfair Mods",
			ModIds = (payload.ModIds ?? new List<string>()),
			Fingerprints = (payload.Fingerprints ?? new List<AntiCheatForbiddenFingerprint>()),
			CreatedUtc = num,
			UpdatedUtc = num
		};
	}

	public static List<AntiCheatForbiddenFingerprint> CloneFingerprints(IEnumerable<AntiCheatForbiddenFingerprint> source)
	{
		string json = JsonSerializer.Serialize(source ?? Array.Empty<AntiCheatForbiddenFingerprint>());
		return JsonSerializer.Deserialize<List<AntiCheatForbiddenFingerprint>>(json) ?? new List<AntiCheatForbiddenFingerprint>();
	}

	private static Payload ReadPayload()
	{
		byte[] buffer = Convert.FromBase64String(CompressedPayloadBase64);
		using MemoryStream stream = new MemoryStream(buffer);
		using GZipStream stream2 = new GZipStream(stream, CompressionMode.Decompress);
		using StreamReader streamReader = new StreamReader(stream2, Encoding.UTF8);
		string json = streamReader.ReadToEnd();
		return JsonSerializer.Deserialize<Payload>(json) ?? new Payload();
	}
}
